import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    static byte[] token() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        while (c > ' ') {
            out.write(c);
            c = read();
        }
        return out.toByteArray();
    }

    public static void main(String[] args) throws IOException {
        byte[] s = token(), t = token();
        long p = nextLong();
        int n = s.length, m = t.length;
        int[] target = new int[26];
        for (byte c : t) target[c - 'a']++;
        long answer = 0;
        // Indices with the same residue mod p form a chain; slide a window of m along each chain.
        for (long r = 0; r < Math.min(p, n); r++) {
            int[] count = new int[26];
            long i = 0;
            for (long idx = r; idx < n; idx += p, i++) {
                count[s[(int) idx] - 'a']++;
                if (i >= m) count[s[(int) (idx - m * p)] - 'a']--;
                if (i >= m - 1 && Arrays.equals(count, target)) answer++;
            }
        }
        System.out.println(answer);
    }
}

