	p := int(nextInt())
	n, m := len(s), len(t)
	var target [26]int32
	for _, c := range t {
		target[c-'a']++
	}
	var answer int64
	// Indices with the same residue mod p form a chain; slide a window of m along each chain.
	for r := 0; r < min(p, n); r++ {
		var count [26]int32
		i := 0
		for idx := r; idx < n; idx += p {
			count[s[idx]-'a']++
			if i >= m {
				count[s[idx-m*p]-'a']--
			}
			if i >= m-1 && count == target {
				answer++
			}
			i++
		}
	}
	fmt.Println(answer)
